import pytest
from click.shell_completion import CompletionItem
from click.testing import CliRunner
from click import Command, Argument, Context, ParamType

class Foo(ParamType):
    def convert(self, value, param, ctx):
        return value

    def shell_complete(self, ctx, param, incomplete):
        return [
            CompletionItem(value=value, help="adsf") for value in
            ["baz:quux", "spam:eggs"]
        ]

def main(foo):
    pass

main = Command(main)
main.params.append(Argument(["foo"], type=Foo()))

def test_zsh_completion():
    runner = CliRunner()
    result = runner.invoke(main, [], env={
        "_FOO_COMPLETE": "zsh_source",
    })
    assert result.exit_code == 0
    # Check if the output contains the expected completion items
    assert "baz:quux   -- adsf" in result.output
    assert "spam:eggs -- adsf" in result.output

if __name__ == "__main__":
    pytest.main([__file__])

from jinja2 import Environment, StrictUndefined

def test_macro_native_types():
    env = Environment(undefined=StrictUndefined, enable_native_types=True)
    template = env.from_string(
        """{%- macro x() -%}{{- [5,6] -}}{%- endmacro -%}{{- x()[0] -}}"""
    )
    result = template.render()
    assert isinstance(result, int), "Expected an integer, got a string"

if __name__ == '__main__':
    test_macro_native_types()

import pytest
from jinja2.nativetypes import NativeEnvironment

def test_native_concat_with_loop_index():
    # Create a template that includes a loop index and a string in a loop
    template = """
    {% block test %}
    {% for i in range(1) %}
        {{ loop.index }}{{ 'a' }}
    {% endfor %}
    {% endblock %}
    {{ self.test() }}
    """
    # Render the template using NativeEnvironment
    env = NativeEnvironment()
    result = env.from_string(template).render()
    # The result should raise a TypeError due to the bug
    assert isinstance(result, str)


def test_native_concat_with_loop_index_and_call():
    # Create a template that includes a loop index and a call to a method
    template = """
    {% block test %}
    {% for i in range(1) %}
        {{ loop.index }}
    {% endfor %}
    {% endblock %}
    {{ self.test() }}
    """
    # Render the template using NativeEnvironment
    env = NativeEnvironment()
    result = env.from_string(template).render()
    # The result should raise a TypeError due to the bug
    assert isinstance(result, str)

